const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".wrap{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:10px;color:var(--ink);font-size:12px;line-height:1.35;display:flex;flex-direction:column;overflow:hidden}\n.wrap *{box-sizing:border-box}\n.card[data-size=\"6x6\"] .wrap{font-size:13px;padding:14px}\n.pg{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.pg.two{flex-direction:row;gap:10px}\n.left{flex:0 0 150px;width:150px;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.left>*{flex:none}\n.card[data-size=\"6x6\"] .left{flex-basis:176px;width:176px;overflow-y:auto;overflow-x:hidden}\n.right{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.right>.tabs,.right>.hint{flex:none}\n.head{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.ttl{margin:0;font-size:14px;font-weight:700;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.btn{font:inherit;cursor:pointer;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:8px;padding:0 10px;min-height:28px}\n.btn:disabled{opacity:.55;cursor:default}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:700}\n.go{flex:none;min-height:34px;width:100%}\n.card[data-size=\"3x3\"] .pg>.go,.left>.go{margin-top:auto}\n.mini{min-height:24px;padding:0 8px;font-size:11px;flex:none}\n.back{min-width:28px;min-height:28px;padding:0;font-size:18px;line-height:1;flex:none}\n.btn:focus-visible,.inp:focus-visible,.row:focus-visible,.cnt:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.sum{flex:none;min-width:0}\n.sl{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11.5px}\n.muted{color:var(--muted)}\n.status{flex:none;font-size:10.5px;word-break:break-word;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3}\n.card[data-size=\"3x3\"] .status{-webkit-line-clamp:2}\n.status.err{color:var(--ink);font-weight:600}\n.cnts{display:flex;gap:6px;flex:none}\n.cnt{flex:1;min-width:0;min-height:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:3px 2px;font:inherit;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;cursor:pointer}\n.cnt.attend{border-color:var(--accent)}\n.num{font-size:18px;line-height:1.1}\n.cl{font-size:10.5px;color:var(--muted)}\n.tabs{display:flex;gap:4px;flex:none;overflow-x:auto;overflow-y:hidden;min-width:0;padding-bottom:2px;scrollbar-width:thin}\n.tab{flex:none;min-height:26px;padding:0 7px;font-size:11px;white-space:nowrap;border-radius:13px;background:transparent}\n.tab.on{background:var(--soft);border-color:var(--accent);font-weight:700}\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:5px;scrollbar-width:thin}\n.row{display:block;flex:none;width:100%;min-width:0;text-align:left;font:inherit;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;padding:6px 8px;cursor:pointer}\n.rtop{display:flex;flex-wrap:wrap;align-items:center;gap:2px 4px;min-width:0}\n.rdate{margin-left:auto;color:var(--muted);font-size:10px;white-space:nowrap}\n.rsub{font-weight:600;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow-wrap:anywhere}\n.rmeta{color:var(--muted);font-size:10.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag{flex:none;font-size:10px;line-height:16px;padding:0 6px;border-radius:8px;white-space:nowrap}\n.tag.attend{background:var(--accent);color:var(--on-accent)}\n.tag.prepare{background:var(--soft);color:var(--ink);border:1px solid var(--accent);line-height:14px}\n.tag.reply{background:transparent;color:var(--ink);border:1px dashed var(--accent-alt);line-height:14px}\n.tag.other{background:transparent;color:var(--muted);border:1px solid var(--line);line-height:14px}\n.empty{flex:1;min-height:0;overflow:auto;color:var(--muted);font-size:11.5px;padding:4px 2px}\n\n.scroll{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}\n.form{display:flex;flex-direction:column;gap:8px;min-width:0}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lab{font-size:11px;font-weight:700}\n.hint{font-size:10px;color:var(--muted);line-height:1.35;overflow-wrap:anywhere}\n.inp{width:100%;min-width:0;min-height:28px;font:inherit;font-size:12px;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:6px;padding:2px 6px}\n.segs{display:flex;flex-wrap:wrap;gap:4px}\n.seg{flex:1 1 auto;min-height:26px;padding:0 8px;font-size:11px;white-space:nowrap}\n.seg.on{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:700}\n.dates{display:flex;flex-direction:column;gap:4px;min-width:0}\n.card[data-size=\"6x3\"] .scroll .dates{flex-direction:row;align-items:center}\n.dates .inp{flex:1}\n.to{font-size:11px;color:var(--muted)}\n.left .to,.card[data-size=\"3x3\"] .to,.card[data-size=\"3x6\"] .to{display:none}\n.sec{font-size:11px;font-weight:700;margin:8px 0 3px;padding-bottom:2px;border-bottom:1px solid var(--line)}\n.why{font-size:11.5px;overflow-wrap:anywhere}\n.kv{display:flex;gap:6px;padding:2px 0;font-size:11.5px;min-width:0}\n.k{flex:none;width:52px;color:var(--muted)}\n.v{flex:1;min-width:0;overflow-wrap:anywhere}\n.dtags{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:2px}\n.scroll>.hint{margin-top:8px}\n";
var CAT_LABEL={attend:'参加',prepare:'准备',reply:'回复',other:'其余'};
var CAT_ORDER=['attend','prepare','reply'];
var RULES=[
['attend',/会议|邀请|邀约|参会|出席|参加|研讨|培训|沙龙|面试|例会|评审会|直播|invitation|invite|meeting|webinar|rsvp/gi],
['prepare',/准备|材料|提交|截止|到期|审阅|审核|审批|汇报|报告|初稿|草稿|方案|交付|跟进|待办|deadline|due date|review|draft|submit|prepare|action required|todo/gi],
['reply',/回复|答复|确认|请问|是否|麻烦|烦请|请告知|请反馈|反馈|意见|回执|尽快|reply|respond|confirm|asap|urgent|\?|？/gi]
];
var FOLDER_SKIP=/sent|draft|trash|deleted|spam|junk|已发送|草稿|垃圾|已删除/i;
var FOLDER_LIKE=/^(inbox|sent|drafts?|trash|spam|junk|archive|收件箱|已发送|草稿箱|垃圾邮件|已删除)/i;
var PRESETS=[['3','近3天'],['7','近7天'],['14','近14天'],['custom','自定义']];

function pad2(n){return n<10?'0'+n:''+n;}
function ymd(ms){var d=new Date(ms);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function shiftDay(s,delta){var p=String(s).split('-');var d=new Date(Number(p[0]),Number(p[1])-1,Number(p[2])+delta);return ymd(d.getTime());}
function fmtAt(ms){if(ms==null)return '时间未知';var d=new Date(ms);return pad2(d.getMonth()+1)+'-'+pad2(d.getDate())+' '+pad2(d.getHours())+':'+pad2(d.getMinutes());}
function toMs(v){
  if(v==null||v==='')return null;
  if(typeof v==='number')return v<1e12?v*1000:v;
  var s=String(v).trim();
  if(/^\d{9,13}$/.test(s)){var n=Number(s);return n<1e12?n*1000:n;}
  var t=Date.parse(s.replace(/^(\d{4})[./](\d{1,2})[./](\d{1,2})/,'$1-$2-$3'));
  return isNaN(t)?null:t;
}
function pick(o,keys){for(var i=0;i<keys.length;i++){var v=o?o[keys[i]]:undefined;if(v!==undefined&&v!==null&&v!=='')return v;}return undefined;}
function who(v){
  if(v===undefined||v===null)return '';
  if(Array.isArray(v))return v.map(who).filter(Boolean).join(', ');
  if(typeof v==='object'){var n=v.name||v.displayName||'';var a=v.address||v.email||v.mail||'';return n&&a?n+' <'+a+'>':(n||a);}
  return String(v);
}
function listOf(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){
    var ks=['messages','items','list','mails','emails','records','results','data'];
    for(var i=0;i<ks.length;i++){if(Array.isArray(d[ks[i]]))return d[ks[i]];}
    var all=Object.keys(d);
    for(var j=0;j<all.length;j++){if(Array.isArray(d[all[j]]))return d[all[j]];}
  }
  return null;
}
function readState(m){
  if(typeof m.unread==='boolean')return m.unread;
  if(typeof m.isUnread==='boolean')return m.isUnread;
  var r=pick(m,['isRead','is_read','read','seen']);
  if(r===undefined)return null;
  return !(r===true||r===1||r==='1'||r==='true');
}
function normMsg(m,idx){
  m=(m&&typeof m==='object')?m:{subject:String(m)};
  var rawBox=who(pick(m,['account','accountEmail','account_email','mailboxAddress','mailbox_address','owner','mailbox']));
  var folder=String(pick(m,['folder','folderName','folder_name','label'])||'');
  if(rawBox&&FOLDER_LIKE.test(rawBox)){if(!folder)folder=rawBox;rawBox='';}
  var att=pick(m,['hasAttachment','hasAttachments','has_attachment','attachments']);
  var id=pick(m,['id','messageId','message_id','uid']);
  return {
    k:id!==undefined?String(id):'i'+idx,
    id:id!==undefined?String(id):'',
    subj:String(pick(m,['subject','title'])||'(无主题)'),
    from:who(pick(m,['from','sender','fromAddress','from_address'])),
    to:who(pick(m,['to','recipients','toAddress','to_address'])),
    box:rawBox,
    folder:folder,
    at:toMs(pick(m,['date','receivedAt','received_at','receivedDate','internalDate','sentAt','sent_at','time','timestamp'])),
    unread:readState(m),
    snip:String(pick(m,['snippet','preview','summary','bodyPreview','body_preview','abstract'])||'').slice(0,240),
    att:att===undefined?null:(Array.isArray(att)?att.length>0:!!att)
  };
}
function classify(m){
  var text=m.subj+' '+m.snip;
  var cats=[],hits=[];
  RULES.forEach(function(r){
    var f=text.match(r[1]);
    if(f&&f.length){
      var u=[];
      f.forEach(function(w){w=w.toLowerCase();if(u.indexOf(w)<0)u.push(w);});
      cats.push(r[0]);
      hits.push(CAT_LABEL[r[0]]+'：'+u.slice(0,3).join('、'));
    }
  });
  if(m.unread===true&&cats.indexOf('reply')<0&&/^\s*(re|回复|答复|回覆)\s*[:：]/i.test(m.subj)){
    cats.push('reply');hits.push('回复：未读的往来邮件(Re:)');
  }
  return {cats:CAT_ORDER.filter(function(c){return cats.indexOf(c)>=0;}),hits:hits};
}
function cfgOf(s){
  var c=(s&&s.cfg)||{};
  return {
    mailbox:c.mailbox||'',
    calendar:c.calendar||'',
    preset:c.preset||'7',
    from:c.from||'',
    to:c.to||'',
    boxes:Array.isArray(c.boxes)?c.boxes:[]
  };
}
function rangeOf(c,today){
  if(c.preset==='custom'){
    var f=c.from||today,t=c.to||today;
    if(f>t){var x=f;f=t;t=x;}
    return {from:f,to:t,name:'自定义'};
  }
  var n=Number(c.preset)||7;
  return {from:shiftDay(today,-(n-1)),to:today,name:'近'+n+'天'};
}
function analyze(raw,c,rng){
  var msgs=raw.map(normMsg);
  var boxes=[];
  msgs.forEach(function(m){if(m.box&&boxes.indexOf(m.box)<0)boxes.push(m.box);});
  var inRange=[];
  msgs.forEach(function(m){
    if(m.folder&&FOLDER_SKIP.test(m.folder))return;
    if(c.mailbox&&m.box&&m.box!==c.mailbox)return;
    if(m.at!==null){var d=ymd(m.at);if(d<rng.from||d>rng.to)return;}
    inRange.push(m);
  });
  inRange.sort(function(a,b){return (b.at||0)-(a.at||0);});
  var items=[],others=[];
  inRange.forEach(function(m){
    var r=classify(m);
    m.cats=r.cats;m.hits=r.hits;
    if(r.cats.length)items.push(m);else others.push(m);
  });
  var boxFilterable=msgs.some(function(m){return !!m.box;});
  return {total:msgs.length,inRange:inRange.length,items:items,others:others,boxes:boxes,boxFilterable:boxFilterable};
}
function withTimeout(p,ms){
  return new Promise(function(ok,no){
    var t=setTimeout(function(){no(new Error('请求超时'));},ms);
    Promise.resolve(p).then(function(v){clearTimeout(t);ok(v);},function(e){clearTimeout(t);no(e);});
  });
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,host,day}=ctx;
  const size=ctx.size;
  const c=cfgOf(state);
  const rng=rangeOf(c,day());
  const res=ui.result||null;
  if(!ui.view)ui.view='home';
  if(!ui.filter)ui.filter='all';

  const kid=(a)=>a.filter((k)=>k!==null&&k!==undefined&&k!==false);
  const T=(tag,cls,...k)=>el(tag,{class:cls},...kid(k));
  const B=(label,cls,fn,dis)=>{
    const a={type:'button',class:'btn '+cls,onclick:fn};
    if(dis)a.disabled=true;
    return el('button',a,label);
  };
  const go=(view,extra)=>{ui.view=view;if(extra)Object.assign(ui,extra);redraw();};
  const saveCfg=(p)=>update((s)=>Object.assign({},s,{cfg:Object.assign({},cfgOf(s),p)})).catch(()=>{
    ui.err='设置保存失败，请重试';redraw();
  });

  async function find(){
    if(ui.busy)return;
    ui.busy=true;ui.err='';redraw();
    try{
      const r=await withTimeout(host.fetchData('connected.mail.message-list'),25000);
      if(!r||r.status!=='ok'){
        throw new Error(String((r&&(r.errorCode||r.status))||'无响应'));
      }
      const raw=listOf(r.data);
      if(!raw)throw new Error('邮件列表格式无法识别');
      const out=analyze(raw,c,rng);
      ui.result=Object.assign({at:Date.now(),from:rng.from,to:rng.to,rname:rng.name,mailbox:c.mailbox,stale:!!r.isStale},out);
      ui.filter='all';
      const same=out.boxes.length===c.boxes.length&&out.boxes.every((b)=>c.boxes.indexOf(b)>=0);
      if(out.boxes.length&&!same){
        await update((s)=>Object.assign({},s,{cfg:Object.assign({},cfgOf(s),{boxes:out.boxes})}));
      }
    }catch(e){
      const msg=String((e&&e.message)||e);
      ui.err=/permission_denied|denied|unauthor/i.test(msg)
        ?'还没有连接邮箱：请先在平台为本卡片连接邮箱，再点查找。'
        :'查找失败：'+msg+(ui.result?'（已保留上次结果）':'');
    }
    ui.busy=false;redraw();
  }

  function tagEls(cats){return cats.map((k)=>T('span','tag '+k,CAT_LABEL[k]));}

  function counts(){
    const items=res?res.items:[];
    const n=(f)=>{
      if(!res)return 0;
      if(f==='all')return items.length;
      if(f==='other')return res.others.length;
      return items.filter((i)=>i.cats.indexOf(f)>=0).length;
    };
    return {n};
  }
  const cn=counts().n;

  function settingsForm(){
    const opts=c.boxes.slice();
    if(c.mailbox&&opts.indexOf(c.mailbox)<0)opts.push(c.mailbox);
    const sel=el('select',{class:'inp',onchange:(e)=>saveCfg({mailbox:e.target.value})},
      el('option',{value:''},'全部已连接邮箱'),
      ...opts.map((b)=>el('option',{value:b},b)));
    sel.value=c.mailbox;
    const cal=el('input',{class:'inp',type:'text',value:c.calendar,placeholder:'日历名称（暂未接入）',
      onchange:(e)=>saveCfg({calendar:e.target.value.trim()})});
    const df=el('input',{class:'inp',type:'date',value:rng.from,
      onchange:(e)=>saveCfg({preset:'custom',from:e.target.value||rng.from,to:rng.to})});
    const dt=el('input',{class:'inp',type:'date',value:rng.to,
      onchange:(e)=>saveCfg({preset:'custom',from:rng.from,to:e.target.value||rng.to})});
    return T('div','form',
      T('label','fld',T('span','lab','邮箱'),sel,
        c.boxes.length?null:T('span','hint','首次查找后会列出已连接的邮箱')),
      T('label','fld',T('span','lab','日历'),cal,
        T('span','hint','日历读取暂未接入：名称只保存，本次不检查日程')),
      T('div','fld',T('span','lab','日期范围'),
        T('div','segs',...PRESETS.map((p)=>B(p[1],'seg'+(c.preset===p[0]?' on':''),
          ()=>saveCfg(p[0]==='custom'?{preset:'custom',from:rng.from,to:rng.to}:{preset:p[0]})))),
        T('div','dates',df,T('span','to','至'),dt)),
      T('div','hint','只读：仅读取邮件信息，不会回复、归档、移动或修改邮件与日程。')
    );
  }

  function mainBtn(){
    return B(ui.busy?'正在读取邮件…':(res?'重新查找':'找出待办'),'primary go',find,ui.busy);
  }

  function summary(){
    const rl=rng.from.slice(5)+' 至 '+rng.to.slice(5);
    return T('div','sum',
      T('div','sl',rng.name+' · '+rl),
      T('div','sl muted','邮箱 '+(c.mailbox||'全部')+' · 日历未接入'));
  }

  function head(title,back,right){
    return T('div','head',
      back?B('‹','back',back):null,
      T('h1','ttl',title),
      right||null);
  }


  const FILTERS=[['all','全部'],['attend','参加'],['prepare','准备'],['reply','回复'],['other','其余']];
  const changed=!!res&&(res.from!==rng.from||res.to!==rng.to||res.mailbox!==c.mailbox);

  function tabs(){
    return T('div','tabs',...FILTERS.map((f)=>B(f[1]+' '+cn(f[0]),'tab'+(ui.filter===f[0]?' on':''),
      ()=>{ui.filter=f[0];redraw();})));
  }

  function row(m){
    return el('button',{type:'button',class:'row',onclick:()=>go('detail',{sel:m.k,back:ui.view})},
      T('div','rtop',...(m.cats.length?tagEls(m.cats):[T('span','tag other','未归类')]),
        T('span','rdate',fmtAt(m.at))),
      T('div','rsub',m.subj),
      T('div','rmeta',(m.from||'发件人未知')+(m.unread===true?' · 未读':'')));
  }

  function listPane(){
    if(!res){
      return T('div','empty',ui.busy?'正在读取邮件…':'选好邮箱、日历和日期范围，点「找出待办」。结果只做列出，不会改动任何邮件或日程。');
    }
    const src=ui.filter==='other'?res.others
      :(ui.filter==='all'?res.items:res.items.filter((i)=>i.cats.indexOf(ui.filter)>=0));
    if(!src.length){
      let t='这一类下没有条目。';
      if(res.inRange===0){
        t='读到邮件 '+res.total+' 封，但 '+res.from.slice(5)+' 至 '+res.to.slice(5)+(res.mailbox?'、邮箱 '+res.mailbox:'')+' 内没有邮件。';
      }else if(ui.filter==='all'){
        t='范围内 '+res.inRange+' 封邮件都没有命中回复/准备/参加的关键词，可到「其余」逐封核对。';
      }
      return T('div','empty',t);
    }
    return T('div','list',...src.map(row));
  }

  function note(){
    if(!res)return null;
    const parts=[];
    if(res.mailbox&&!res.boxFilterable)parts.push('邮件未标明所属邮箱，邮箱选择未生效');
    parts.push('按主题/摘要关键词初筛，非 AI 判断，请对照来源邮件核对');
    return T('div','hint',parts.join('；')+'。');
  }

  function statusLine(short){
    if(ui.err)return T('div','status err','⚠ '+ui.err);
    if(ui.busy)return T('div','status','正在读取邮件…');
    if(!res)return T('div','status muted','还没有查找结果');
    const tail=changed?' · 设置已改，需重新查找':'';
    if(short){
