        statusLine(true),
        mainBtn());
    }
    if(size==='6x3'){
      return T('div','pg two',
        T('div','left',head('查漏事项',null,openSettings()),summary(),statusLine(false),mainBtn()),
        T('div','right',tabs(),listPane(),note()));
    }
    if(size==='3x6'){
      return T('div','pg',
        head('查漏事项',null,openSettings()),
        summary(),mainBtn(),statusLine(false),tabs(),listPane(),note());
    }
    return T('div','pg two',
      T('div','left scroll',head('查漏事项',null,null),settingsForm(),statusLine(false),mainBtn()),
      T('div','right',tabs(),listPane(),note()));
  }

  let view=ui.view;
  const picked=view==='detail'?findMsg():null;
  if(view==='detail'&&!picked)view='home';
  if(view==='settings'&&size==='6x6')view='home';
  if(view==='list'&&size!=='3x3')view='home';

  let page;
  if(view==='detail')page=detail(picked);
  else if(view==='settings'){
    page=T('div','pg',head('设置',()=>go('home')),T('div','scroll',settingsForm()));
  }else if(view==='list'){
    page=T('div','pg',head(ui.filter==='all'?'全部事项':CAT_LABEL[ui.filter]+'事项',()=>go('home')),tabs(),listPane());
  }else page=home();

  root.appendChild(T('div','wrap',page));
}

